+void KlassTrainingData::remove_invalid_references() {
+  if (!is_valid()) {
+    _comp_deps.clear();
+    return;
+  }
+  int j = 0;
+  for (int i = 0; i < _comp_deps.length(); i++) {
+    CompileTrainingData* ctd = _comp_deps.at(i);
+    if (ctd->is_valid()) {
+      if (i != j) {
+        _comp_deps.at_put(j, ctd);
+      }
+      j++;
+    }
+  }
+  _comp_deps.trunc_to(j);
+}
